DECLARE client uuid:=gen_random_uuid();partner uuid:=gen_random_uuid();resource uuid:=gen_random_uuid();app uuid;other_app uuid;offer uuid;other_offer uuid;version text;offer_version text;r jsonb;
 client_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex');partner_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex');
BEGIN
 INSERT INTO public.client_profiles(id,display_name,contact) VALUES(client,'QA capacity client','test-only');
 INSERT INTO public.partners(id,public_name,status) VALUES(partner,'QA capacity partner','ACTIVE');
 INSERT INTO public.catalog_items(id,public_id,title,entity_type,booking_capacity,owner_partner_id,availability_status,publication_status,moderation_status,client_price_thb) VALUES(resource,'QA-'||resource,'QA property pool','PROPERTY',2,partner,'AVAILABLE','PUBLISHED','APPROVED',1000);
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','CLIENT','profile_id',client,'hash',client_hash));
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','PARTNER','profile_id',partner,'hash',partner_hash));
 r:=pcs.portal_action(client_hash,'request',gen_random_uuid(),'{"need":"QA property dates"}');app:=(r->>'application_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_admin_action('assign-partner',jsonb_build_object('application_id',app,'expected_version',version,'partner_id',partner));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 r:=pcs.portal_action(partner_hash,'submit-offer',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'price','2000','deposit','200','terms','QA two units','catalog_item_id',resource,'start_date','2115-01-10','end_date','2115-01-20','booking_quantity','2'));offer:=(r->>'offer_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;SELECT updated_at::text INTO offer_version FROM public.pcs_partner_offers WHERE id=offer;
 PERFORM pcs.portal_admin_action('review-offer',jsonb_build_object('application_id',app,'expected_version',version,'offer_id',offer,'offer_version',offer_version,'decision','APPROVED'));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_action(client_hash,'select-offer',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version,'offer_id',offer));
 IF NOT EXISTS(SELECT 1 FROM public.applications WHERE id=app AND category='general' AND qualification_data->>'resource_capacity_booking'='true' AND item_id=resource AND qualification_data->>'booking_quantity'='2') THEN RAISE EXCEPTION 'QA property offer not allocated';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(pcs.portal_home(client_hash)->'applications') a WHERE a->>'id'=app::text AND a->>'booking_quantity'='2') THEN RAISE EXCEPTION 'QA accepted quantity hidden';END IF;
 BEGIN UPDATE public.applications SET qualification_data=qualification_data||'{"booking_quantity":"1"}' WHERE id=app;RAISE EXCEPTION 'QA agreed quantity changed';EXCEPTION WHEN check_violation THEN NULL;END;
 r:=pcs.portal_action(client_hash,'request',gen_random_uuid(),'{"need":"QA competing unit"}');other_app:=(r->>'application_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=other_app;PERFORM pcs.portal_admin_action('assign-partner',jsonb_build_object('application_id',other_app,'expected_version',version,'partner_id',partner));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=other_app;
 r:=pcs.portal_action(partner_hash,'submit-offer',gen_random_uuid(),jsonb_build_object('application_id',other_app,'expected_version',version,'price','1000','deposit','0','terms','QA one unit','catalog_item_id',resource,'start_date','2115-01-12','end_date','2115-01-15','booking_quantity','1'));other_offer:=(r->>'offer_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=other_app;SELECT updated_at::text INTO offer_version FROM public.pcs_partner_offers WHERE id=other_offer;
 PERFORM pcs.portal_admin_action('review-offer',jsonb_build_object('application_id',other_app,'expected_version',version,'offer_id',other_offer,'offer_version',offer_version,'decision','APPROVED'));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=other_app;
 BEGIN PERFORM pcs.portal_action(client_hash,'select-offer',gen_random_uuid(),jsonb_build_object('application_id',other_app,'expected_version',version,'offer_id',other_offer));RAISE EXCEPTION 'QA cabinet oversold property';EXCEPTION WHEN exclusion_violation THEN NULL;END;
 IF (SELECT status FROM public.pcs_partner_offers WHERE id=other_offer)<>'APPROVED' OR (SELECT selected_partner_offer_id FROM public.applications WHERE id=other_app) IS NOT NULL THEN RAISE EXCEPTION 'QA capacity rejection partly committed';END IF;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_action(partner_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_action(client_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version));
 UPDATE public.applications SET operational_status='CANCELLED_BY_CLIENT' WHERE id=app;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=other_app;PERFORM pcs.portal_action(client_hash,'select-offer',gen_random_uuid(),jsonb_build_object('application_id',other_app,'expected_version',version,'offer_id',other_offer));
END;
